namespace diamond {

std::vector<std::string> rows(char letter) {
    const int n = letter - 'A';
    const int width = 2 * n + 1;
    std::vector<std::string> top;

    for (int i = 0; i <= n; ++i) {
        char current = static_cast<char>('A' + i);
        std::string row(width, ' ');
        int outer = n - i;
        row[outer] = current;
        row[width - 1 - outer] = current;
        top.push_back(row);
    }

    std::vector<std::string> result(top);
    for (int i = static_cast<int>(top.size()) - 2; i >= 0; --i) {
        result.push_back(top[i]);
    }
    return result;
}

}  // namespace diamond
